/**
 * Airpay AI Assistant chat bubble — client-side controller.
 *
 * @module     local_airpay_assistant/chat
 * @copyright  2026 Airpay Payment Services
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define("local_airpay_assistant/chat", [
    "core/ajax",
    "core/notification"
], function(Ajax, Notification) {
    "use strict";

    var SELECTORS = {
        ROOT:     "#airpay-assistant",
        TOGGLE:   "#airpay-assistant-toggle",
        PANEL:    "#airpay-assistant-panel",
        MINIMIZE: "#airpay-assistant-minimize",
        MESSAGES: "#airpay-assistant-messages",
        INPUT:    "#airpay-assistant-input",
        SEND:     "#airpay-assistant-send",
        QUICK:    ".airpay-assistant__quick-actions button"
    };
    var CLASSES = {
        HIDDEN:  "airpay-assistant__panel--hidden",
        VISIBLE: "airpay-assistant__panel--visible"
    };
    var ALLOWED_TAGS = {
        P: 1, STRONG: 1, EM: 1, B: 1, I: 1, CODE: 1, PRE: 1, BR: 1,
        UL: 1, OL: 1, LI: 1, A: 1, BLOCKQUOTE: 1, HR: 1, SPAN: 1
    };
    var ALLOWED_ATTRS = { href: 1, title: 1, lang: 1, dir: 1 };

    var initialised = false;
    var panelOpen = false;
    var sending = false;

    function openPanel() {
        var panel = document.querySelector(SELECTORS.PANEL);
        var toggle = document.querySelector(SELECTORS.TOGGLE);
        var input = document.querySelector(SELECTORS.INPUT);
        if (!panel || !toggle) {
            return;
        }
        panel.style.display = "flex";
        void panel.offsetWidth;
        panel.classList.remove(CLASSES.HIDDEN);
        panel.classList.add(CLASSES.VISIBLE);
        toggle.setAttribute("aria-expanded", "true");
        var iconOpen = toggle.querySelector(".airpay-assistant__icon-open");
        var iconClose = toggle.querySelector(".airpay-assistant__icon-close");
        if (iconOpen) { iconOpen.style.display = "none"; }
        if (iconClose) { iconClose.style.display = ""; }
        if (input) {
            window.setTimeout(function() { input.focus(); }, 50);
        }
        panelOpen = true;
    }

    function closePanel() {
        var panel = document.querySelector(SELECTORS.PANEL);
        var toggle = document.querySelector(SELECTORS.TOGGLE);
        if (!panel || !toggle) {
            return;
        }
        panel.classList.remove(CLASSES.VISIBLE);
        panel.classList.add(CLASSES.HIDDEN);
        toggle.setAttribute("aria-expanded", "false");
        var iconOpen = toggle.querySelector(".airpay-assistant__icon-open");
        var iconClose = toggle.querySelector(".airpay-assistant__icon-close");
        if (iconOpen) { iconOpen.style.display = ""; }
        if (iconClose) { iconClose.style.display = "none"; }
        window.setTimeout(function() {
            if (!panelOpen) { panel.style.display = "none"; }
        }, 300);
        toggle.focus();
        panelOpen = false;
    }

    function sanitiseNode(node) {
        if (node.nodeType === Node.TEXT_NODE) {
            return document.createTextNode(node.textContent);
        }
        if (node.nodeType !== Node.ELEMENT_NODE) {
            return null;
        }
        if (!ALLOWED_TAGS[node.tagName]) {
            var frag = document.createDocumentFragment();
            for (var i = 0; i < node.childNodes.length; i++) {
                var c = sanitiseNode(node.childNodes[i]);
                if (c) { frag.appendChild(c); }
            }
            return frag;
        }
        var safe = document.createElement(node.tagName);
        for (var j = 0; j < node.attributes.length; j++) {
            var attr = node.attributes[j];
            if (!ALLOWED_ATTRS[attr.name]) { continue; }
            if (attr.name === "href") {
                var v = (attr.value || "").trim().toLowerCase();
                if (v.indexOf("javascript:") === 0 || v.indexOf("data:") === 0) { continue; }
            }
            safe.setAttribute(attr.name, attr.value);
        }
        for (var k = 0; k < node.childNodes.length; k++) {
            var sc = sanitiseNode(node.childNodes[k]);
            if (sc) { safe.appendChild(sc); }
        }
        return safe;
    }

    function safeAppendHtml(target, html) {
        var doc = new DOMParser().parseFromString("<body>" + html + "</body>", "text/html");
        if (!doc.body) {
            target.textContent = String(html);
            return;
        }
        var nodes = Array.prototype.slice.call(doc.body.childNodes);
        for (var i = 0; i < nodes.length; i++) {
            var s = sanitiseNode(nodes[i]);
            if (s) { target.appendChild(s); }
        }
    }

    function renderMessage(text, role, isHtml) {
        var messages = document.querySelector(SELECTORS.MESSAGES);
        if (!messages) { return; }
        var wrap = document.createElement("div");
        wrap.className = "airpay-assistant__msg airpay-assistant__msg--" + role;
        if (isHtml) {
            safeAppendHtml(wrap, text);
        } else {
            var p = document.createElement("p");
            p.textContent = text;
            p.style.margin = "0";
            wrap.appendChild(p);
        }
        messages.appendChild(wrap);
        messages.scrollTop = messages.scrollHeight;
    }

    function showTyping() {
        var messages = document.querySelector(SELECTORS.MESSAGES);
        if (!messages) { return null; }
        var wrap = document.createElement("div");
        wrap.className = "airpay-assistant__msg airpay-assistant__msg--typing";
        wrap.setAttribute("aria-label", "Assistant is typing");
        for (var i = 0; i < 3; i++) {
            var dot = document.createElement("span");
            dot.className = "airpay-assistant__dot";
            wrap.appendChild(dot);
        }
        messages.appendChild(wrap);
        messages.scrollTop = messages.scrollHeight;
        return wrap;
    }

    function submitMessage(overrideText) {
        if (sending) { return; }
        var input = document.querySelector(SELECTORS.INPUT);
        var send = document.querySelector(SELECTORS.SEND);
        if (!input || !send) { return; }
        var text = (overrideText || input.value || "").trim();
        if (!text) { return; }

        sending = true;
        send.disabled = true;
        input.disabled = true;
        input.value = "";

        renderMessage(text, "user");
        var typing = showTyping();

        Ajax.call([{
            methodname: "local_airpay_assistant_ask",
            args: { query: text }
        }])[0].then(function(result) {
            if (typing) { typing.remove(); }
            var responseText = (result && result.response)
                || "Sorry, I had trouble understanding that.";
            renderMessage(responseText, "bot", true);
        }).catch(function(err) {
            if (typing) { typing.remove(); }
            Notification.exception(err);
            renderMessage(
                "I had trouble reaching the assistant. Please try again in a moment.",
                "bot"
            );
        }).finally(function() {
            sending = false;
            send.disabled = false;
            input.disabled = false;
            input.focus();
        });
    }

    function init() {
        if (initialised) { return; }
        var root = document.querySelector(SELECTORS.ROOT);
        if (!root) { return; }
        initialised = true;

        var toggle = root.querySelector(SELECTORS.TOGGLE);
        var minimize = root.querySelector(SELECTORS.MINIMIZE);
        var input = root.querySelector(SELECTORS.INPUT);
        var send = root.querySelector(SELECTORS.SEND);

        if (toggle) {
            toggle.addEventListener("click", function() {
                if (panelOpen) { closePanel(); } else { openPanel(); }
            });
        }
        if (minimize) {
            minimize.addEventListener("click", closePanel);
        }
        if (input) {
            input.addEventListener("input", function() {
                if (send) { send.disabled = input.value.trim().length === 0; }
            });
            input.addEventListener("keydown", function(ev) {
                if (ev.key === "Enter" && !ev.shiftKey) {
                    ev.preventDefault();
                    submitMessage();
                }
            });
        }
        if (send) {
            send.addEventListener("click", function() { submitMessage(); });
        }
        var chips = root.querySelectorAll(SELECTORS.QUICK);
        for (var i = 0; i < chips.length; i++) {
            (function(btn) {
                btn.addEventListener("click", function() {
                    var query = btn.dataset.query || btn.textContent.trim();
                    submitMessage(query);
                });
            })(chips[i]);
        }

        // Global keyboard shortcuts — manifesto §4.1.
        document.addEventListener("keydown", function(ev) {
            if (ev.key === "k" && (ev.metaKey || ev.ctrlKey)
                    && !ev.shiftKey && !ev.altKey) {
                ev.preventDefault();
                if (!panelOpen) { openPanel(); } else { closePanel(); }
                return;
            }
            if (ev.key === "Escape" && panelOpen) {
                ev.preventDefault();
                closePanel();
            }
        });
    }

    return { init: init };
});
